INSERT INTO extension_projects (extension_program_id, college_id, academic_program_id, campus, title, leader_name, year, total_budget, target_participants, status, source) SELECT ep.id, ep.college_id, (SELECT id FROM academic_programs WHERE name = 'BS in Agricultural Business'), NULL, 'CO-GROW: Cooperative Growth through Responsive Operations and Wise Governance.', 'Aimee P. Olpenda', 2027, 14020.00, 105, 'planned', '2027 Monitoring Sheet' FROM extension_programs ep INNER JOIN colleges c ON c.id = ep.college_id WHERE c.code = 'CAFES' AND ep.name = 'Resource-based Enterprise Development' AND NOT EXISTS (SELECT 1 FROM extension_projects ex WHERE ex.extension_program_id = ep.id AND ex.title = 'CO-GROW: Cooperative Growth through Responsive Operations and Wise Governance.' AND ex.campus IS NULL);
